<?php
declare(strict_types=1);
require_once __DIR__.'/../standalone/bootstrap.php';
require_once __DIR__.'/../autoloader.php';
require_once __DIR__.'/../Repository/ConfigManagerRepository.php';
require_once __DIR__.'/../Service/ConfigManagerService.php';
require_once __DIR__.'/../Controller/ConfigManagerController.php';
require_once __DIR__.'/../lib/config_manager_runtime.php';
if (!mmbb_has_service('ConfigManager')) { http_response_code(403); echo 'Forbidden'; exit; }
use ConfigManager\Repository\ConfigManagerRepository; use ConfigManager\Service\ConfigManagerService; use ConfigManager\Controller\ConfigManagerController;
if(session_status()===PHP_SESSION_NONE)session_start(); if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32)); $csrf=(string)$_SESSION['csrf_token'];
function cb_json(array $x,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control:no-store');echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function cb_servers():array{return cm_load_config_manager_servers(__DIR__.'/../config/config.php');}
function cb_find(array $servers,string $name):array{foreach($servers as $s)if(strcasecmp((string)($s['name']??''),$name)===0)return $s;throw new RuntimeException('Unbekannter Server.',404);}
function cb_ctl(array $server):ConfigManagerController{return new ConfigManagerController(new ConfigManagerService(new ConfigManagerRepository($server)));}
function cb_body():array{$x=json_decode((string)file_get_contents('php://input'),true);if(!is_array($x))throw new InvalidArgumentException('Ungültiges JSON.');return $x;}
function cb_unwrap(array $r):array{$c=(int)($r['http_code']??500);$x=is_array($r['response']??null)?$r['response']:[];if($c<200||$c>=300||empty($x['ok']))throw new RuntimeException((string)($x['error']??('Agent HTTP '.$c)),$c>=400&&$c<=599?$c:502);return $x;}
try{
 $servers=cb_servers();
 if(($_GET['api']??'')==='summary') {
  $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
  $host = preg_replace('/[^A-Za-z0-9.:-]/','',(string)($_SERVER['HTTP_HOST']??'config-manager.local')) ?: 'config-manager.local';
  $base = rtrim((string)(cfg('CONFIG_MANAGER_PUBLIC_BASE_URL') ?: ($scheme.'://'.$host)),'/');
  cb_json(['ok'=>true,
    'servers'=>array_map(fn($s)=>['name'=>(string)($s['name']??'')],$servers),
  ]);
}
 if(($_GET['api']??'')==='load'){ $srv=cb_find($servers,trim((string)($_GET['server']??''))); cb_json(['ok'=>true,'info'=>cb_unwrap(cb_ctl($srv)->getClientBaselineInfo())]); }
 if($_SERVER['REQUEST_METHOD']==='POST'){
  $in=cb_body(); if(!hash_equals($csrf,(string)($in['csrf_token']??''))) throw new RuntimeException('CSRF fehlgeschlagen.',403); $srv=cb_find($servers,trim((string)($in['server_name']??''))); $ctl=cb_ctl($srv); $a=(string)($in['action']??'');
  if($a==='monit_config')cb_json(['ok'=>true,'result'=>cb_unwrap($ctl->saveClientMonitBaseline((array)($in['config']??[])))]);
  if($a==='monit_test')cb_json(['ok'=>true,'result'=>cb_unwrap($ctl->testClientMonitBaseline())]);
  throw new RuntimeException('Unbekannte Aktion.',400);
 }
}catch(Throwable $e){$c=(int)$e->getCode();cb_json(['ok'=>false,'error'=>$e->getMessage()],$c>=400&&$c<=599?$c:500);}
?>
