<div class="bl-grid mb-3">
 <div class="bl-card"><div class="d-flex justify-content-between"><h5>Config Agent</h5><span id="agentState"></span></div><div class="bl-kv"><span>Version</span><strong id="agentVersion">—</strong><span>Dienst</span><strong id="agentService">—</strong><span>Host-ID</span><strong id="hostId">—</strong><span>Labels</span><strong id="hostLabels">—</strong></div><div class="form-text mt-3">Steuerkanal des Config Managers. Auf registrierten Hosts bereits vorhanden.</div></div>
 <div class="bl-card"><div class="d-flex justify-content-between"><h5>Monit</h5><span class="badge text-bg-secondary">RPM verwaltet</span></div><div class="bl-kv"><span>Paket</span><strong id="monitPkg">—</strong><span>Dienst</span><strong id="monitService">—</strong><span>Zugang</span><strong id="monitCred">—</strong><span>Status-Zugriff</span><strong id="monitProbe">nicht geprüft</strong><span>Exporter-Paket</span><strong id="monitExporter">—</strong></div><ul class="bl-install-list"><li>lokaler HTTP/XML-Zugang <code>127.0.0.1:2812</code></li><li>Secret <code>/var/lib/service/config-agent/secrets/monit-status.env</code></li><li>Benutzer/Passwort setzen oder rotieren</li><li>Verbindung für Server Health testen</li><li>Monit-Paket, Exporter und Alloy werden hier <strong>nicht</strong> installiert</li></ul><div class="bl-sep"></div><div class="alert alert-secondary py-2 small mb-2"><strong>Prinzip:</strong> Monit bleibt lokal auf <code>127.0.0.1</code>. Das Passwort wird auf dem Zielserver als geschütztes Secret gespeichert. Der Config Agent verwendet diesen Zugang automatisch für Server Health.</div><div class="row g-2"><div class="col-md-5"><label class="form-label small">Bind-Adresse</label><input id="monitBind" class="form-control form-control-sm" value="127.0.0.1"></div><div class="col-md-3"><label class="form-label small">Port</label><input id="monitPort" type="number" class="form-control form-control-sm" value="2812"></div><div class="col-md-4"><label class="form-label small">Benutzer</label><input id="monitUser" class="form-control form-control-sm" value="monitadmin"></div><div class="col-12"><label class="form-label small">Passwort setzen / rotieren</label><input id="monitPass" type="password" class="form-control form-control-sm" autocomplete="new-password" placeholder="leer lassen = vorhandenes Passwort beibehalten"><div class="form-text">Neues Passwort: mindestens 12 Zeichen. Wird nicht im Browser zurückgelesen.</div></div></div><div class="d-flex flex-wrap gap-2 mt-2"><button id="saveMonit" class="btn btn-sm btn-success">Speichern & aktivieren</button><button id="testMonit" class="btn btn-sm btn-outline-primary">Verbindung testen</button></div><div class="form-text mt-2">Secret: <code id="monitSecretPath">/var/lib/service/config-agent/secrets/monit-status.env</code> · erwartet: <code>0600 root:root</code>. Service-spezifische Monit-Checks bleiben Git-/Managed-Config-konfiguriert. Softwareinstallation erfolgt über das Deploy-Profil <code>observability-client</code>.</div></div>

</div>
<div class="card"><div class="card-header fw-semibold">Klare Trennung</div><div class="card-body"><div class="row"><div class="col-md-6"><h6>Client Baseline</h6><ul><li>Config Agent / Host-ID</li><li>Monit HTTP/XML-Zugang</li><li>Monit Credential</li><li>Server-Health-Verbindungstest</li></ul></div><div class="col-md-6"><h6>Deployment über Git</h6><ul><li><strong>Deploy-Profil:</strong> <code>observability-client</code></li><li>Monit-Paket</li><li>Grafana Alloy</li><li>Monit Prometheus Exporter</li><li>Alloy Basiskonfiguration</li></ul><a class="btn btn-sm btn-outline-primary" href="git_deploy.php">Git Deploy öffnen</a></div></div></div></div>
</div></main><?php require MMBB_UI.'/includes/js.php';?>
<script>
const CSRF=<?=json_encode($csrf)?>,DEFAULT_SERVER=<?=json_encode(trim((string)($_GET['server']??'')))?>,$=id=>document.getElementById(id);let DATA={};
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function msg(t,type='info'){$('msg').innerHTML=`<div class="alert alert-${type} py-2">${esc(t)}</div>`}
async function api(u,o={}){const r=await fetch(u,o),j=await r.json().catch(()=>({ok:false,error:'Ungültige Antwort'}));if(!r.ok||j.ok===false)throw new Error(j.error||`HTTP ${r.status}`);return j}
async function load(){try{const j=await api('client_baseline.php?api=load&server='+encodeURIComponent($('server').value));DATA=j.info.baseline||{};const ident=j.info.identity||{};$('hostId').textContent=ident.host_id||'—';$('hostLabels').textContent=Object.entries(ident.labels||{}).map(([k,v])=>k+'='+v).join(', ')||'—';$('agentVersion').textContent=DATA.config_agent?.version||'—';$('agentService').textContent=DATA.config_agent?.service?.active?'aktiv':'inaktiv';$('agentState').innerHTML=DATA.config_agent?.service?.active?'<span class="badge text-bg-success">OK</span>':'<span class="badge text-bg-danger">Fehler</span>';const m=DATA.monit||{},mc=m.configuration||{};$('monitPkg').textContent=m.installed?`installiert ${m.version||''}`:'nicht installiert';$('monitService').textContent=m.service?.active?'aktiv':(m.installed?'inaktiv':'—');$('monitBind').value=mc.bind||'127.0.0.1';$('monitPort').value=mc.port||2812;$('monitUser').value=mc.username||'monitadmin';$('monitCred').innerHTML=mc.secret_present?'<span class="text-success">gesetzt</span>':'<span class="text-warning">nicht gesetzt</span>';$('monitSecretPath').textContent=mc.secret_file||'/var/lib/service/config-agent/secrets/monit-status.env';const me=m.exporter||{};$('monitExporter').innerHTML=me.healthy?`<span class="text-success">aktiv · ${esc(me.version||'')}</span>`:(me.installed?'<span class="text-warning">installiert / nicht bereit</span>':'<span class="text-body-secondary">nicht installiert</span>');$('monitProbe').textContent='nicht geprüft';const mon=!!m.installed;['monitBind','monitPort','monitUser','monitPass','saveMonit','testMonit'].forEach(id=>$(id).disabled=!mon);msg(mon?'Baseline-Status geladen.':'Monit ist nicht installiert. Bitte zuerst das Deploy-Profil observability-client ausrollen.',mon?'success':'warning')}catch(e){msg(e.message,'danger')}finally{window.setTimeout(()=>{if(window.mmbbBusyReset)window.mmbbBusyReset()},0)}}
async function post(action,extra={}){return api('client_baseline.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,server_name:$('server').value,action,...extra})})}
async function init(){const j=await api('client_baseline.php?api=summary');$('server').innerHTML=j.servers.map(s=>`<option>${esc(s.name)}</option>`).join('');if(DEFAULT_SERVER&&j.servers.some(s=>s.name===DEFAULT_SERVER))$('server').value=DEFAULT_SERVER;if(j.servers.length)await load()}
$('reload').onclick=load;$('server').onchange=load;$('saveMonit').onclick=async()=>{try{await post('monit_config',{config:{bind:$('monitBind').value,port:Number($('monitPort').value),username:$('monitUser').value,password:$('monitPass').value}});$('monitPass').value='';msg('Monit-Zugang und Credential gespeichert.','success');await load()}catch(e){msg(e.message,'danger')}};$('testMonit').onclick=async()=>{try{$('monitProbe').innerHTML='<span class="text-body-secondary">prüfe…</span>';const r=await post('monit_test');$('monitProbe').innerHTML='<span class="text-success">OK'+(r.result?.version?' · '+esc(r.result.version):'')+'</span>';msg('Config Agent kann Monit lokal authentisiert auslesen.','success')}catch(e){$('monitProbe').innerHTML='<span class="text-danger">Fehler</span>';msg('Monit-Test fehlgeschlagen: '+e.message,'danger')}};init();
</script></body></html>
